const item = $input.first();
const input = item.json;
const binary = item.binary || {};
const binaryKeys = Object.keys(binary);
const firstBinaryField = binaryKeys[0] || 'data';
const isForm = input['Sujet de la reunion'] !== undefined;
const isPlatformWebhook = input.source_system !== undefined || input.recording_delivery !== undefined || input.recording_url !== undefined || input.meeting_reference !== undefined;

const normalizeAudioLanguageCode = (value) => {
  const raw = String(value || 'fr').trim().toLowerCase();
  const match = raw.match(/\(([a-z]{2})\)/);
  if (match) return match[1];
  const map = {
    francais: 'fr', français: 'fr', french: 'fr', fr: 'fr',
    anglais: 'en', english: 'en', en: 'en',
    espagnol: 'es', español: 'es', spanish: 'es', es: 'es',
    arabe: 'ar', arabic: 'ar', ar: 'ar',
    portugais: 'pt', portuguais: 'pt', portuguese: 'pt', pt: 'pt'
  };
  return map[raw] || raw.slice(0, 2) || 'fr';
};

const normalizeOutputLanguage = (value) => {
  const raw = String(value || 'Francais').trim().toLowerCase();
  if (['anglais', 'english', 'en'].includes(raw)) {
    return { label: 'Anglais', code: 'en', htmlLang: 'en' };
  }
  if (['espagnol', 'español', 'spanish', 'es'].includes(raw)) {
    return { label: 'Espagnol', code: 'es', htmlLang: 'es' };
  }
  return { label: 'Francais', code: 'fr', htmlLang: 'fr' };
};

const normalizeDeliverable = (value) => {
  const raw = String(value || 'Les deux').trim().toLowerCase();
  if (['email client', 'client email', 'correo cliente', 'email', 'mail client'].includes(raw)) return 'Email client';
  if (['compte rendu', 'meeting report', 'report', 'informe', 'reporte'].includes(raw)) return 'Compte rendu';
  return 'Les deux';
};

const normalizeMaskingLevel = (value) => {
  const raw = String(value || 'Strict').trim().toLowerCase();
  if (['standard', 'std'].includes(raw)) return 'Standard';
  return 'Strict';
};

const slugSource = (value) => String(value || 'meeting-platform')
  .trim()
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/^_+|_+$/g, '') || 'meeting_platform';

if (isForm) {
  const sujet = input['Sujet de la reunion'] || 'Reunion';
  const participants = input['Participants (separes par virgule)'] || 'Non precise';
  const reunion_date = input['Date de la reunion'] || new Date().toISOString().slice(0, 10);
  const email_destinataire = input['Email destinataire final'] || 'contact@transferai.ci';
  const email_validateur = input['Email validateur'] || email_destinataire;
  const audio_url = input['Ou lien Google Drive'] || '';
  const recording_url = input['URL directe du recording (optionnel)'] || '';
  const mode_ingestion = input['Mode d\'ingestion'] || 'Upload manuel';
  const meeting_reference = input['Reference meeting / join URL'] || '';
  const source_object = input['Objet source / dossier source'] || '';
  const langue_code = normalizeAudioLanguageCode(input['Langue audio'] || 'Francais (fr)');
  const outputLanguage = normalizeOutputLanguage(input['Langue de sortie'] || 'Francais');
  const livrable = normalizeDeliverable(input['Livrable demande'] || 'Les deux');
  const entites_sensibles = input['Entites sensibles a masquer'] || '';
  const niveau_masquage = normalizeMaskingLevel(input['Niveau de masquage'] || 'Strict');
  const source_label = input["Source de l'enregistrement"] || 'Formulaire';
  const source_type = audio_url ? 'drive_url' : 'upload';
  return [{
    binary,
    json: {
      sujet,
      participants,
      reunion_date,
      email_destinataire,
      email_validateur,
      audio_url,
      recording_url,
      mode_ingestion,
      meeting_reference,
      source_object,
      langue_code,
      langue_sortie: outputLanguage.label,
      langue_sortie_code: outputLanguage.code,
      langue_sortie_html: outputLanguage.htmlLang,
      livrable,
      entites_sensibles,
      niveau_masquage,
      source_label,
      source_system: slugSource(source_label),
      source_type,
      audio_binary_field: 'Fichier audio',
      session_id: `intl_cr_${Date.now()}`,
      timestamp: new Date().toISOString()
    }
  }];
}

if (isPlatformWebhook) {
  const sujet = input.sujet || input.meeting_title || input.topic || 'Reunion';
  const participants = input.participants || 'Non precise';
  const reunion_date = input.reunion_date || input.meeting_date || new Date().toISOString().slice(0, 10);
  const email_destinataire = input.email_destinataire || 'contact@transferai.ci';
  const email_validateur = input.email_validateur || email_destinataire;
  const langue_code = normalizeAudioLanguageCode(input.langue_audio || input.langue_code || 'fr');
  const outputLanguage = normalizeOutputLanguage(input.langue_sortie || input.output_language || input.langue_sortie_code || 'Francais');
  const source_system = slugSource(input.source_system || input.source_label || 'meeting-platform');
  return [{
    binary,
    json: {
      sujet,
      participants,
      reunion_date,
      email_destinataire,
      email_validateur,
      audio_url: input.audio_url || input.drive_url || '',
      recording_url: input.recording_url || '',
      mode_ingestion: input.recording_delivery || 'Webhook plateforme',
      meeting_reference: input.meeting_reference || input.join_web_url || input.meeting_id || '',
      source_object: input.source_object || input.drive_file_id || input.recording_id || '',
      langue_code,
      langue_sortie: outputLanguage.label,
      langue_sortie_code: outputLanguage.code,
      langue_sortie_html: outputLanguage.htmlLang,
      livrable: normalizeDeliverable(input.livrable || input.deliverable || 'Les deux'),
      entites_sensibles: input.entites_sensibles || '',
      niveau_masquage: normalizeMaskingLevel(input.niveau_masquage || input.masking_level || 'Strict'),
      source_label: input.source_label || input.source_system || 'Webhook plateforme',
      source_system,
      source_type: binaryKeys.length ? 'upload' : (input.audio_url ? 'drive_url' : 'upload'),
      audio_binary_field: firstBinaryField,
      session_id: input.session_id || `intl_cr_${Date.now()}`,
      timestamp: new Date().toISOString()
    }
  }];
}

const outputLanguage = normalizeOutputLanguage(input.langue_sortie || 'Francais');
const sujet = (input.name || 'Reunion').replace(/\.(mp3|m4a|wav|ogg|mp4|webm|opus)$/i, '');
return [{
  json: {
    sujet,
    participants: 'Non precise',
    reunion_date: new Date().toISOString().slice(0, 10),
    email_destinataire: 'contact@transferai.ci',
    email_validateur: 'contact@transferai.ci',
    audio_url: input.id ? `https://drive.google.com/uc?id=${input.id}&export=download` : '',
    recording_url: '',
    mode_ingestion: 'Dossier surveille',
    meeting_reference: '',
    source_object: input.id || '',
    langue_code: 'fr',
    langue_sortie: outputLanguage.label,
    langue_sortie_code: outputLanguage.code,
    langue_sortie_html: outputLanguage.htmlLang,
    livrable: 'Les deux',
    entites_sensibles: '',
    niveau_masquage: 'Strict',
    source_label: 'Google Drive',
    source_system: 'google_drive',
    source_type: 'drive_url',
    drive_file_id: input.id,
    audio_binary_field: null,
    session_id: `intl_cr_${Date.now()}`,
    timestamp: new Date().toISOString()
  }
}];

const resp = $input.first().json;
const segments = resp.segments || [];
return Promise.all(segments.map(async (seg, idx) => ({
  json: { index: idx + 1, filename: seg.filename || `segment_${idx + 1}.mp3` },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(seg.data_base64, 'base64'), seg.filename || `segment_${idx + 1}.mp3`, 'audio/mpeg') }
})));

const items = $input.all();
const meta = $('Normaliser les donnees').first().json;
const parts = [];
for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  const text = (row.text || '').trim();
  if (!text) continue;
  parts.push(`Segment ${i + 1}\n${text}`);
}
return [{ json: { ...meta, full_transcript: parts.join('\n\n'), transcript_segment_count: parts.length } }];

const src = $input.first().json;
const table = {};
const counters = { PARTY: 1, EMAIL: 1, PHONE: 1, URL: 1, ID: 1 };

const nextToken = (prefix) => `${prefix}_${String(counters[prefix]++).padStart(3, '0')}`;
const esc = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const addMapping = (prefix, raw) => {
  const clean = (raw || '').trim();
  if (!clean) return null;
  const existing = Object.entries(table).find(([, value]) => value.toLowerCase() === clean.toLowerCase());
  if (existing) return existing[0];
  const token = nextToken(prefix);
  table[token] = clean;
  return token;
};

let transcript = src.full_transcript || '';
let subject = src.sujet || '';
let participants = src.participants || '';

const replaceAllTargets = (matcher, replacer) => {
  transcript = transcript.replace(matcher, replacer);
  subject = subject.replace(matcher, replacer);
  participants = participants.replace(matcher, replacer);
};

const exactEntities = [
  ...String(src.participants || '').split(',').map(v => v.trim()),
  ...String(src.entites_sensibles || '').split(/[;,\n]/).map(v => v.trim())
].filter(v => v && v.length > 2).sort((a, b) => b.length - a.length);

for (const entity of exactEntities) {
  const token = addMapping('PARTY', entity);
  if (!token) continue;
  replaceAllTargets(new RegExp(`\\b${esc(entity)}\\b`, 'gi'), token);
}

replaceAllTargets(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, (match) => addMapping('EMAIL', match));
replaceAllTargets(/\+?\d[\d\s().-]{7,}\d/g, (match) => addMapping('PHONE', match));
replaceAllTargets(/https?:\/\/[^\s]+/gi, (match) => addMapping('URL', match));
replaceAllTargets(/\b[A-Z0-9_-]{8,}\b/g, (match) => addMapping('ID', match));

const pii_entries = Object.entries(table).map(([token, value]) => ({ token, value }));

return [{ json: {
  ...src,
  sensitive_table: table,
  pii_entries,
  pseudonymized_subject: subject,
  pseudonymized_participants: participants,
  pseudonymized_transcript: transcript,
  pii_count: pii_entries.length
} }];

