={{ JSON.stringify({
  model: 'gpt-5',
  store: false,
  input: [
    {
      role: 'system',
      content: [
        {
          type: 'input_text',
          text: 'You are an international meeting-report specialist serving corporations, international organizations, embassies, chancelleries, and public-sector stakeholders. You only receive pseudonymized content. Never invent facts. If a detail is uncertain, write [to clarify]. Supported output languages are Francais, Anglais, and Espagnol. All user-facing fields, section headings, reports, and email text must be written strictly in the requested output language. Produce two outputs: one internal pseudonymized report for the validator, and one external sanitized report plus a sanitized follow-up email for the client. Keep aliases such as PARTY_001 exactly as they are. Avoid exposing raw identifiers or guessing identities.'
        }
      ]
    },
    {
      role: 'user',
      content: [
        {
          type: 'input_text',
          text: `Output language: ${$json.langue_sortie} (${String($json.langue_sortie_code || '').toLowerCase() || 'fr'})\nDeliverable requested: ${$json.livrable}\nMasking level: ${$json.niveau_masquage}\nPseudonymized subject: ${$json.pseudonymized_subject}\nPseudonymized participants: ${$json.pseudonymized_participants}\nMeeting date: ${$json.reunion_date}\n\nPseudonymized transcript:\n${$json.pseudonymized_transcript}`
        }
      ]
    }
  ],
  text: {
    format: {
      type: 'json_schema',
      name: 'meeting_pack',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        required: [
          'title_sanitized',
          'executive_summary',
          'discussion_points',
          'decisions',
