const response = $input.first().json;
const prev = $('Pseudonymiser localement').first().json;
let raw = '';
for (const item of response.output || []) {
  if (item.type !== 'message') continue;
  for (const content of item.content || []) {
    if (content.type === 'output_text' && content.text) {
      raw = content.text;
      break;
    }
  }
  if (raw) break;
}
if (!raw && response.output_text) raw = response.output_text;
const parsed = JSON.parse(raw || '{}');
return [{ json: { ...prev, llm_raw: raw, llm_parsed: parsed } }];

const src = $input.first().json;
const map = src.sensitive_table || {};
let internalClear = src.llm_parsed.internal_report_markdown || '';
for (const [token, value] of Object.entries(map).sort((a, b) => b[0].length - a[0].length)) {
  internalClear = internalClear.replaceAll(token, value);
}
return [{ json: { ...src, internal_report_clear: internalClear } }];

const src = $input.first().json;
const store = $getWorkflowStaticData('global');
const sid = src.session_id;
const llm = src.llm_parsed || {};
const esc = (value) => String(value || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const outputCode = String(src.langue_sortie_code || '').toLowerCase() || (
  String(src.langue_sortie || '').toLowerCase().startsWith('ang') ? 'en' :
  String(src.langue_sortie || '').toLowerCase().startsWith('esp') ? 'es' :
  'fr'
);

const i18n = {
  fr: {
    htmlLang: 'fr',
    emailBlock: 'Email client sanitise',
    reportBlock: 'Compte rendu client sanitise',
    internalBlock: 'Version interne reidentifiee - validation uniquement',
    previewTitle: 'Validation livrable sensible',
    previewHeading: 'Validation requise - livrable sensible',
    protectionLabel: 'Protection active :',
    protectionText: 'donnees sensibles tokenisees avant l\'appel OpenAI. La version finale client reste sanitisee.',
    approve: 'Approuver et envoyer',
    reject: 'Rejeter',
    validatorPrefix: '[Validation requise]',
    validatorFallback: 'Compte rendu sensible',
    finalFallback: 'Compte rendu',
    archivePrefix: 'sanitized_meeting_report'
  },
  en: {
    htmlLang: 'en',
    emailBlock: 'Sanitized client email',
    reportBlock: 'Sanitized client meeting report',
    internalBlock: 'Re-identified internal version - validation only',
    previewTitle: 'Sensitive deliverable validation',
    previewHeading: 'Validation required - sensitive deliverable',
    protectionLabel: 'Active protection:',
    protectionText: 'sensitive data elements tokenized before the OpenAI call. The final client version remains sanitized.',
    approve: 'Approve and send',
    reject: 'Reject',
    validatorPrefix: '[Validation required]',
    validatorFallback: 'Sensitive meeting report',
    finalFallback: 'Meeting report',
    archivePrefix: 'sanitized_meeting_report'
  },
  es: {
    htmlLang: 'es',
    emailBlock: 'Correo al cliente sanitizado',
    reportBlock: 'Informe de reunion sanitizado para el cliente',
    internalBlock: 'Version interna reidentificada - solo para validacion',
    previewTitle: 'Validacion de entregable sensible',
    previewHeading: 'Validacion requerida - entregable sensible',
    protectionLabel: 'Proteccion activa:',
    protectionText: 'datos sensibles tokenizados antes de la llamada a OpenAI. La version final para el cliente permanece sanitizada.',
    approve: 'Aprobar y enviar',
    reject: 'Rechazar',
    validatorPrefix: '[Validacion requerida]',
    validatorFallback: 'Informe de reunion sensible',
    finalFallback: 'Informe de reunion',
    archivePrefix: 'sanitized_meeting_report'
  }
};

const t = i18n[outputCode] || i18n.fr;
const toHtmlBlock = (title, content) => `<div style="margin:18px 0"><h3 style="margin-bottom:8px;color:#10263F">${esc(title)}</h3><pre style="white-space:pre-wrap;background:#f7f9fc;border:1px solid #d9e2ec;padding:16px;border-radius:8px;font-family:Menlo,monospace;font-size:12px;line-height:1.6">${esc(content)}</pre></div>`;
const externalEmail = llm.sanitized_email_body || '';
const externalReport = llm.external_report_markdown || '';
const internalClear = src.internal_report_clear || '';

let finalBody = '';
if (src.livrable === 'Email client') {
  finalBody = toHtmlBlock(t.emailBlock, externalEmail);
} else if (src.livrable === 'Compte rendu') {
  finalBody = toHtmlBlock(t.reportBlock, externalReport);
} else {
  finalBody = toHtmlBlock(t.emailBlock, externalEmail) + toHtmlBlock(t.reportBlock, externalReport);
}

const previewHtml = `<!DOCTYPE html><html lang="${t.htmlLang}"><head><meta charset="UTF-8"><title>${esc(t.previewTitle)}</title></head><body style="font-family:Arial,sans-serif;max-width:920px;margin:auto;padding:28px;color:#17212b">
  <div style="background:#10263F;color:white;padding:20px 24px;border-radius:10px">
    <h1 style="margin:0;font-size:22px">${esc(t.previewHeading)}</h1>
    <p style="margin:8px 0 0 0;opacity:.85">Session ${esc(sid)} | ${esc(src.sujet)} | ${esc(src.reunion_date)}</p>
  </div>
  <div style="background:#FFF8E6;border:1px solid #F4B400;padding:16px;border-radius:10px;margin-top:18px">
    <strong>${esc(t.protectionLabel)}</strong> ${esc(src.pii_count)} ${esc(t.protectionText)}
  </div>
  ${finalBody}
  ${toHtmlBlock(t.internalBlock, internalClear)}
  <div style="margin-top:24px;padding:18px;border-top:1px solid #d9e2ec">
    <a href="https://n8n-pxlk.srv1480638.hstgr.cloud/webhook/cr-intl-approve?sid=${encodeURIComponent(sid)}" style="display:inline-block;padding:12px 18px;background:#1f8f4e;color:white;text-decoration:none;border-radius:8px;margin-right:8px">${esc(t.approve)}</a>
    <a href="https://n8n-pxlk.srv1480638.hstgr.cloud/webhook/cr-intl-reject?sid=${encodeURIComponent(sid)}" style="display:inline-block;padding:12px 18px;background:#c0392b;color:white;text-decoration:none;border-radius:8px">${esc(t.reject)}</a>
  </div>
</body></html>`;

const finalHtml = `<!DOCTYPE html><html lang="${t.htmlLang}"><head><meta charset="UTF-8"><title>${esc(llm.title_sanitized || t.finalFallback)}</title></head><body style="font-family:Arial,sans-serif;max-width:860px;margin:auto;padding:28px;color:#17212b">${finalBody}</body></html>`;
const archiveHtml = `<!DOCTYPE html><html lang="${t.htmlLang}"><head><meta charset="UTF-8"><title>${esc(llm.title_sanitized || sid)}</title></head><body style="font-family:Arial,sans-serif;max-width:860px;margin:auto;padding:28px;color:#17212b">${toHtmlBlock(t.reportBlock, externalReport)}</body></html>`;
const finalSubject = llm.sanitized_email_subject || `${t.finalFallback} - ${sid}`;
const validatorSubject = `${t.validatorPrefix} ${src.sujet_original || src.sujet || t.validatorFallback}`;

store[sid] = {
  final_subject: finalSubject,
  final_html: finalHtml,
  archive_html: archiveHtml,
  preview_html: previewHtml,
  email_destinataire: src.email_destinataire,
  sujet_original: src.sujet,
  validator_subject: validatorSubject,
  archive_lang: t.htmlLang,
  archive_prefix: t.archivePrefix
};

return [{ json: {
  session_id: sid,
  preview_html: previewHtml,
  final_html: finalHtml,
  archive_html: archiveHtml,
  final_subject: finalSubject,
  validator_subject: validatorSubject,
  email_destinataire: src.email_destinataire,
  email_validateur: src.email_validateur,
  sujet_original: src.sujet,
  pii_count: src.pii_count,
  archive_lang: t.htmlLang,
  archive_prefix: t.archivePrefix
} }];

const sid = $json.query?.sid || $json.sid || '';
if (!sid) throw new Error('Session ID manquant');
const store = $getWorkflowStaticData('global');
const data = store[sid];
if (!data) throw new Error(`Aucune session trouvee pour ${sid}`);
return [{ json: { sid, ...data } }];

const data = $input.first().json;
const langSuffix = data.archive_lang || 'fr';
const prefix = data.archive_prefix || 'sanitized_meeting_report';
const fileName = `${prefix}_${data.sid}_${langSuffix}.html`;
const binary = await this.helpers.prepareBinaryData(Buffer.from(data.archive_html || data.final_html || '<p>Archive empty</p>', 'utf8'), fileName, 'text/html');
return [{ json: { ...data, archive_file_name: fileName }, binary: { data: binary } }];
